/* ---------- Answer action bar ---------- */
/* every action on an answer in one raised rail under it: copy, regenerate with its versions, thumbs, and read aloud, which
   widens into a progress bar and a clock and lights each word as it reads it */
.aab{display:flex;flex-direction:column;gap:var(--dm-s-3)}
/* no room kept for a longer answer or an empty status line, in every style (owner's notes, 18 Nov): the answer is as tall as
   its words, the reasons and the status take room only while they show, and the component grows with them (grow()). While
   a new version streams in, the answer keeps the height of the one it replaces, then eases to its own. The bar's shadow
   shows past the growing box */
.aab.growing{overflow-clip-margin:32px}
.aab-why{transition:grid-template-rows var(--dm-t) var(--dm-ease),opacity var(--dm-t) var(--dm-ease),margin-top var(--dm-t) var(--dm-ease)}
.aab-why.shut{margin-top:calc(-1 * var(--dm-s-3));transition:grid-template-rows var(--dm-t) var(--dm-ease),opacity var(--dm-t) var(--dm-ease),margin-top var(--dm-t) var(--dm-ease),visibility 0s var(--dm-t)}
/* nothing in the bar shrinks or swells on a click (owner, 18 Nov): a rated thumb only tilts */
.aab-bar .ib:active{transform:none}
:root[data-style="clean"] .aab-bar .ib:active,:root [data-style="clean"] .aab-bar .ib:active,:root [data-style="clean"].aab-bar .ib:active{transform:none}
/* (the word being read is lit with small corners, so a short word's highlight stays a rounded box, not a near-circle) */
.aab-t .w{transition:background .16s,color .16s;border-radius:calc(3px * var(--dm-rk))}
.aab-t .w.in{animation:aabw .42s var(--dm-ease) both}
@keyframes aabw{from{opacity:0;filter:blur(4px)}to{opacity:1;filter:none}}
.aab-t.out{animation:aabo .32s var(--dm-ease) both}
@keyframes aabo{to{opacity:0;filter:blur(4px);transform:translateY(-2px)}}
.aab-t .nw{background:var(--dm-hl-ok);border-radius:0}
.aab-t .w.rd{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.aab-row{display:flex;align-items:center;flex-wrap:nowrap;gap:var(--dm-s-2) var(--dm-s-3)}
.aab-row>.aab-bar{flex:none}
.aab-bar{display:inline-flex;align-items:center;gap:1px;padding:3px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.aab-bar .ib{width:28px;height:28px}
.aab-bar .ib[disabled]{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis)}
.aab-bar .ib svg{transition:transform .42s var(--dm-ease)}
.aab-re.go svg{transform:rotate(360deg)}
.aab-up[aria-pressed="true"]{color:var(--dm-ok);background:var(--dm-ok-bg)}
.aab-dn[aria-pressed="true"]{color:var(--dm-bad);background:var(--dm-bad-bg)}
.aab-up[aria-pressed="true"] svg,.aab-dn[aria-pressed="true"] svg{transform:rotate(-8deg)}
.aab-sep{width:1px;height:16px;background:var(--dm-line);margin:0 var(--dm-s-1)}
/* the version pager only takes room once there is a second version */
.aab-pg{display:inline-flex;align-items:center;max-width:0;overflow:hidden;opacity:0;transition:max-width .42s var(--dm-ease),opacity .32s}
.aab-pg.on{max-width:96px;opacity:1}
/* (the versions' arrows are the bar's own 28px icon buttons) */
.aab-pg .ib{width:28px;height:28px}
.aab-n{font-size:12px;color:var(--dm-muted);min-width:32px;text-align:center}
.aab-rd{display:inline-flex;align-items:center;height:28px;padding:0 7px;border-radius:var(--dm-r-pill);color:var(--dm-fg2);transition:background .16s,color .16s}
@media (hover:hover) and (pointer:fine){.aab-rd:hover{background:var(--dm-row)}}
.aab-rd .ic{display:grid;place-items:center;width:14px}
.aab-rd[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.aab-rd.paused{background:var(--dm-chip-fill);color:var(--dm-fg2)}
.aab-pr{width:0;height:3px;border-radius:var(--dm-r-tiny,2px);background:color-mix(in srgb,currentColor 22%,transparent);overflow:hidden;margin-left:0;transition:width .42s var(--dm-ease),margin .42s var(--dm-ease)}
.aab-pr i{display:block;height:100%;width:0;background:currentColor;border-radius:inherit}
.aab-tm{font-size:11.5px;max-width:0;overflow:hidden;white-space:nowrap;transition:max-width .42s var(--dm-ease),margin .42s var(--dm-ease)}
.aab-rd.on .aab-pr{width:56px;margin-left:var(--dm-s-2)}
.aab-rd.on .aab-tm{max-width:80px;margin-left:var(--dm-s-2)}
.aab-meta{flex:0 1 auto;min-width:0;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aab-wy{display:flex;flex-direction:column;gap:var(--dm-s-2);padding:2px 0 var(--dm-s-1)}
.aab-wq{font-size:13px;font-weight:500}
.aab-ch{display:flex;flex-wrap:wrap;gap:6px}
/* the reasons sit on the stage: unpicked, a step above the chip's own grey and a step more under the pointer, as Feedback
   sheet's are (owner, 23 Nov: "could these be a bit darker?"); a picked one is the accent tint. Clean keeps its own (below) */
.aab-ch .chip{background:var(--dm-hover)}
@media (hover:hover) and (pointer:fine){.aab-ch .chip:hover{background:var(--dm-press)}}
.aab-ch .chip.on{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));box-shadow:none}
.aab-st{margin:0;max-height:20px;font-size:12.5px;display:flex;align-items:center;gap:6px;transition:max-height var(--dm-t) var(--dm-ease),margin-top var(--dm-t) var(--dm-ease)}
.aab-st:is(:empty,.off){max-height:0;margin-top:calc(-1 * var(--dm-s-3))}
.aab-st.warn{color:var(--dm-warn)}
.aab-st.ok svg{color:var(--dm-ok);flex:none}
.aab-rd.on .aab-pr{width:40px}
@media (max-width:480px){.aab-rd.on .aab-tm{display:none}.aab-row{flex-direction:column;align-items:flex-start}.aab-meta{max-width:100%}}
/* Clean (owner, 18 Nov): the chrome is monochrome: a rated thumb fills in ink on the selected fill in its round shape (owner, 23 Nov), with no green or red and no tilt, read aloud plays in ink on a grey track and lights the word
   it reads in grey, and a picked reason is an ink chip like a toggle that is on. What a new version changed stays green, and
   so does the status's tick; a problem stays amber. Words fade in and out without a blur */
@keyframes aabwc{from{opacity:0}to{opacity:1}}
@keyframes aaboc{to{opacity:0;transform:translateY(-2px)}}
:root[data-style="clean"] .aab-bar,:root [data-style="clean"] .aab-bar,:root [data-style="clean"].aab-bar{border-radius:calc(28px / 2 + 3px)}
:root[data-style="clean"] .aab-t .w.in,:root [data-style="clean"] .aab-t .w.in,:root [data-style="clean"].aab-t .w.in{animation-name:aabwc;animation-duration:var(--dm-t-slow)}
:root[data-style="clean"] .aab-t.out,:root [data-style="clean"] .aab-t.out,:root [data-style="clean"].aab-t.out{animation-name:aaboc;animation-duration:var(--dm-t)}
:root[data-style="clean"] .aab-bar .ib[aria-pressed="true"] svg,:root [data-style="clean"] .aab-bar .ib[aria-pressed="true"] svg,:root [data-style="clean"].aab-bar .ib[aria-pressed="true"] svg{transform:none}
/* (the word being read is lit a step darker than the chip's next grey, so it shows on the stage) */
:root[data-style="clean"] .aab-t .w.rd,:root [data-style="clean"] .aab-t .w.rd,:root [data-style="clean"].aab-t .w.rd{background:var(--dm-press);color:var(--dm-fg)}
:root[data-style="clean"] .aab-bar .ib[aria-pressed="true"],:root [data-style="clean"] .aab-bar .ib[aria-pressed="true"],:root [data-style="clean"].aab-bar .ib[aria-pressed="true"]{background:var(--dm-row-on);color:var(--dm-fg)}
:root[data-style="clean"] .aab-bar .ib[aria-pressed="true"] svg,:root [data-style="clean"] .aab-bar .ib[aria-pressed="true"] svg,:root [data-style="clean"].aab-bar .ib[aria-pressed="true"] svg{fill:currentColor}
:root[data-style="clean"] .aab-rd[aria-pressed="true"],:root [data-style="clean"] .aab-rd[aria-pressed="true"],:root [data-style="clean"].aab-rd[aria-pressed="true"]{background:var(--dm-row-on);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .aab-rd:hover,:root [data-style="clean"] .aab-rd:hover,:root [data-style="clean"].aab-rd:hover{background:var(--dm-row)}}
:root[data-style="clean"] .aab-ch .chip.on,:root [data-style="clean"] .aab-ch .chip.on,:root [data-style="clean"].aab-ch .chip.on{background:var(--dm-btn-2);color:var(--dm-on-btn);box-shadow:inset 0 0 0 1px var(--dm-btn-2)}
/* a reason not picked takes the one hover over its fill, easing over 220ms (owner, 21 Nov); on the stage its grey is two steps
   above the chip's own, so it shows there as a chip does on a card */
:root[data-style="clean"] .aab-ch .chip:not(.on),:root [data-style="clean"] .aab-ch .chip:not(.on),:root [data-style="clean"].aab-ch .chip:not(.on){background:var(--dm-press)}
:root[data-style="clean"] .aab-ch .chip,:root [data-style="clean"] .aab-ch .chip,:root [data-style="clean"].aab-ch .chip{transition:background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .aab-ch .chip:not(.on):hover,:root [data-style="clean"] .aab-ch .chip:not(.on):hover,:root [data-style="clean"].aab-ch .chip:not(.on):hover{background:var(--dm-press);box-shadow:inset 0 0 0 99px var(--dm-row)}}
:root[data-style="clean"] .aab-st.ok svg,:root [data-style="clean"] .aab-st.ok svg,:root [data-style="clean"].aab-st.ok svg{color:var(--dm-ok-mark)}

DM.def('answer-action-bar', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{copy}', I('copy')).replace('{re}', I('refresh')).replace('{l}', I('chev-l','xs')).replace('{rr}', I('chev-r','xs'))
    .replace('{up}', I('up-thumb')).replace('{dn}', I('down-thumb')).replace('{vol}', I('vol','xs'));
  // the versions a regenerate writes, in turn. [[…]] marks what changed from the version before; $24 to $19 a month saves 21%
  const POOL = [
    { t:'Pro is $24 a month, or $19 a month when billed yearly. That saves 15%, and yearly is the option the new pricing page shows first.', meta:'Sonnet 5.5 · 6.2s' },
    { t:'Pro is $24 a month, or $19 a month billed yearly, which saves [[21%, or $60 a year]]. The new pricing page shows the yearly price first.', meta:'Sonnet 5.5 · 4.8s' },
    { t:'Billed yearly, Pro drops from $24 to $19 a month: [[$60 back each year]], about 21%. That is why the pricing page leads with yearly.', meta:'Sonnet 5.5 · 5.1s' }
  ];
  const t = $('.aab-t', r), pg = $('.aab-pg', r), n = $('.aab-n', r), pv = $('.aab-prev', r), nx = $('.aab-next', r), re = $('.aab-re', r), cp = $('.aab-cp', r);
  const up = $('.aab-up', r), dn = $('.aab-dn', r), rd = $('.aab-rd', r), bar = $('.aab-pr i', r), tm = $('.aab-tm', r), meta = $('.aab-meta', r), why = $('.aab-why', r), st = $('.aab-st', r), chips = $$('.aab-ch .chip', r);
  // every version keeps its own rating
  const vers = [{ ...POOL[0], rate:'' }]; let cur = 0, busy = false, failOnce = false;
  const plain = v => v.t.replace(/\[\[|\]\]/g, '');
  // each word's HTML, with the space before it; inside the changed phrase the space is highlighted too, so the phrase reads as one
  const words = v => { let on = false; return v.t.split(' ').map((w, i) => { const a = w.startsWith('[['), b = w.includes(']]'), inner = on && !a; if (a) on = true;
    const s = (i ? `<span${inner ? ' class="nw"' : ''}> </span>` : '') + `<span class="w${on ? ' nw' : ''}">${w.replace(/\[\[|\]\]/g, '')}</span>`; if (b) on = false; return s; }); };
  // the tone changes with the words: the words fading out keep their colour, and the new ones arrive in theirs (swap()
  // writes them 170ms on)
  const status = (text, tone) => { clearTimeout(st._tone); const set = () => { st.classList.toggle('warn', tone === 'warn'); st.classList.toggle('ok', tone === 'ok'); };
    if (tone === 'ok') { set(); st.innerHTML = `${I('ok','xs')}<span>${text}</span>`; enter(st); return; }
    const lag = !REDUCE && !!st.textContent.trim() && st.textContent !== text; swap(st, text); if (lag) st._tone = setTimeout(set, 170); else set(); };
  function nav(){
    n.textContent = (cur + 1) + ' / ' + vers.length; pg.classList.toggle('on', vers.length > 1); pg.inert = vers.length < 2;
    pv.disabled = cur === 0 || busy; nx.disabled = cur === vers.length - 1 || busy; re.disabled = busy;
    up.setAttribute('aria-pressed', vers[cur].rate === 'up'); dn.setAttribute('aria-pressed', vers[cur].rate === 'down');
    swap(meta, vers[cur].meta);
  }
  // no room kept for a longer answer or an empty status, in every style (owner, 18 Nov). The component grows with what it
  // shows (grow(), once its entrance has settled), and a version streaming in keeps the height of the one it replaces, then
  // eases to its own
  const aab = $('.aab', r);
  Promise.resolve().then(() => Promise.all(aab.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && aab.isConnected) c.offs.push(grow(aab)); });
  const keep = () => { if (t.textContent.trim()) t.style.minHeight = t.offsetHeight + 'px'; };
  const fit = () => { if (!t.style.minHeight) return; const was = t.offsetHeight; t.style.minHeight = ''; const h = t.offsetHeight; if (h >= was || REDUCE) return;
    t.style.minHeight = was + 'px'; void t.offsetHeight; t.style.transition = 'min-height var(--dm-t) var(--dm-ease)'; t.style.minHeight = h + 'px';
    c.later(460, () => { t.style.transition = ''; t.style.minHeight = ''; }); };
  // a version streams in word by word; paging between versions shows one at once
  async function stream(v){
    keep(); t.classList.add('out'); await c.wait(260); t.classList.remove('out'); t.innerHTML = '';
    const ws = words(v);
    for (let i = 0; i < ws.length; i++){ t.insertAdjacentHTML('beforeend', ws[i]); t.lastElementChild.classList.add('in'); await c.wait(38); }
    fit();
  }
  async function show(i){ stop(); cur = i; nav(); t.classList.add('out'); await c.wait(240); t.classList.remove('out'); t.innerHTML = words(vers[i]).join(''); $$('.w', t).forEach((w, k) => { w.classList.add('in'); w.style.animationDelay = k * 10 + 'ms'; }); }
  pv.onclick = () => c.run(() => show(cur - 1));
  nx.onclick = () => c.run(() => show(cur + 1));
  // regenerate writes the next version; a dropped connection is retried once with a countdown
  function regenerate(note){
    if (busy) return; stop(); busy = true; re.classList.add('go'); c.later(700, () => re.classList.remove('go')); nav();
    c.run(async () => {
      if (failOnce){ failOnce = false;
        status('Writing a new version' + (note ? ' with your note' : '')); st.classList.add('shim'); await c.wait(1200); st.classList.remove('shim');
        for (let k = 2; k > 0; k--){ status(`Couldn't reach the model. Retrying in ${k}s`, 'warn'); await c.wait(1000); }
      }
      status('Writing a new version' + (note ? ' with your note' : '')); st.classList.add('shim');
      const v = { ...POOL[Math.min(vers.length, POOL.length - 1)], rate:'' }; vers.push(v); cur = vers.length - 1; nav();
      await stream(v); busy = false; nav(); st.classList.remove('shim');
      // what the new version fixed, when it answers a reason; the pager already counts the versions
      if (note) status('Fixes the saving: 21%, not 15%', 'ok'); else status('');
    });
  }
  re.onclick = () => regenerate();
  // the tooltip says it was copied, and how
  cp.onclick = () => copied(cp, plain(vers[cur]), 'Copied without the highlights');
  // thumbs: up is a quiet thanks; down asks why, and a reason writes a version that answers it
  up.onclick = () => { const v = vers[cur]; v.rate = v.rate === 'up' ? '' : 'up'; why.classList.add('shut'); nav(); status(v.rate ? 'Thanks, noted for this project' : ''); };
  dn.onclick = () => { const v = vers[cur]; v.rate = v.rate === 'down' ? '' : 'down'; why.classList.toggle('shut', v.rate !== 'down'); why.inert = v.rate !== 'down'; nav(); status(''); chips.forEach(x => x.classList.remove('on')); };
  chips.forEach(ch => ch.onclick = () => { chips.forEach(x => x.classList.toggle('on', x === ch)); c.later(400, () => { why.classList.add('shut'); why.inert = true; failOnce = vers.length === 1; regenerate(ch.textContent); }); });
  why.inert = true;
  // read aloud: about 0.28s a word, each word lit as it's read, with a progress bar and a clock
  let reading = 0, pos = 0;
  const clock = s => Math.floor(s / 60) + ':' + String(Math.floor(s) % 60).padStart(2, '0');
  const icon = k => { $('.ic', rd).innerHTML = I(k, 'xs'); };
  // stop drops the place (a new version, another page); pause keeps it, so the bar, the clock and the lit word stay
  function stop(){ if (reading) clearInterval(reading); reading = 0; pos = 0; rd.classList.remove('on', 'paused'); rd.setAttribute('aria-pressed', 'false'); rd.setAttribute('aria-label', 'Read aloud'); rd.dataset.tip = 'Read aloud'; icon('vol'); bar.style.width = '0%'; $$('.w.rd', t).forEach(w => w.classList.remove('rd')); }
  function pause(){ clearInterval(reading); reading = 0; rd.classList.add('paused'); rd.setAttribute('aria-pressed', 'false'); rd.setAttribute('aria-label', 'Resume reading'); rd.dataset.tip = 'Resume'; icon('play'); }
  rd.onclick = () => {
    if (reading) return pause();
    const ws = $$('.w', t); if (!ws.length || busy) return;
    const total = ws.length * .28;
    rd.classList.add('on'); rd.classList.remove('paused'); rd.setAttribute('aria-pressed', 'true'); rd.setAttribute('aria-label', 'Pause reading'); rd.dataset.tip = 'Pause'; icon('pause');
    reading = c.every(100, () => {
      pos += 100 / 280; const i = Math.min(ws.length - 1, Math.floor(pos));
      ws.forEach((w, k) => w.classList.toggle('rd', k === i));
      bar.style.width = Math.min(100, pos / ws.length * 100) + '%'; tm.textContent = clock(pos * .28) + ' / ' + clock(total);
      if (pos >= ws.length) stop();
    });
  };
  // Left and Right move between the toolbar's buttons, skipping any that are switched off
  c.on($('.aab-bar', r), 'keydown', e => {
    const k = { ArrowRight:1, ArrowLeft:-1 }[e.key]; if (!k) return;
    const bs = $$('.aab-bar button', r).filter(b => !b.disabled && !b.closest('[inert]')), i = bs.indexOf(document.activeElement);
    if (i < 0) return; e.preventDefault(); bs[(i + k + bs.length) % bs.length].focus({ preventScroll:true });
  });
  nav();
  c.run(async () => { busy = true; nav(); await c.wait(300); await stream(vers[0]); busy = false; nav(); });
  // the preview's story: listen, hear a wrong number, rate it down, say why, ride out a dropped connection, copy the fix
  c.story(async s => {
    await s.until(() => !busy); await s.beat(2);
    await s.tap(rd); s.away(); await s.beat(7);
    await s.tap(rd); await s.beat(1);
    await s.tap(dn); s.away(); await s.beat(3);
    await s.tap(chips[0]); s.away();
    await s.until(() => vers.length > 1 && !busy); await s.beat(3);
    await s.tap(cp); s.away(); await s.beat(1);
  });
});
